import React from 'react';

function Presentation() {
  return (
    <section className="presentation">
      <div className="presentation-container">
        <div className="presentation-logo">CF</div>
        <div className="presentation-content">
          <h1 className="presentation-title">Cooperativa de Trabajadores Informáticos</h1>
          <h2 className="presentation-subtitle">"Código Fidel"</h2>
          <p className="presentation-description">
            Somos una cooperativa dedicada al desarrollo de software y soluciones tecnológicas,
            comprometida con el trabajo colaborativo y la excelencia técnica. Nuestro equipo
            de profesionales trabaja conjuntamente para transformar ideas en soluciones digitales
            que impulsan el crecimiento de nuestros clientes.
          </p>
        </div>
      </div>
    </section>
  );
}

export default Presentation;
